-- Masterface: cok dil (TR/EN/DE) gecisi. Tekrar calistirilabilir, veri silmez.
begin;
alter table categories add column if not exists i18n jsonb;
alter table projects add column if not exists i18n jsonb;
alter table services add column if not exists i18n jsonb;
alter table stats add column if not exists i18n jsonb;
alter table process_steps add column if not exists i18n jsonb;
alter table form_fields add column if not exists i18n jsonb;
update services set i18n = '{"en":{"title":"Festival and Event Management","description":"We manage the entire process for the festivals and events your brand wants to be part of: from organizer negotiations and space agreements to contracts, stand setup and staff management."},"de":{"title":"Festival- und Eventmanagement","description":"Für die Festivals und Events, bei denen Ihre Marke präsent sein möchte, übernehmen wir den gesamten Prozess: von Gesprächen mit den Veranstaltern und Flächenvereinbarungen über Verträge bis zu Standaufbau und Personalmanagement."}}'::jsonb where title = 'Festival ve Etkinlik Yönetimi' and i18n is null;
update services set i18n = '{"en":{"title":"Roadshows and Mobile Events","description":"We bring your brand to consumers in different cities, squares and public spaces. With product launches, sampling and creative field activities, we deliver high-energy, memorable events that grab attention."},"de":{"title":"Roadshows und mobile Events","description":"Wir bringen Ihre Marke in verschiedenen Städten, auf Plätzen und in Lebensräumen zu den Konsumenten. Mit Produktpräsentationen, Sampling und kreativen Aktionen vor Ort realisieren wir aufmerksamkeitsstarke, energiegeladene und einprägsame Events."}}'::jsonb where title = 'Roadshow ve Mobil Etkinlikler' and i18n is null;
update services set i18n = '{"en":{"title":"Sampling and Tasting Events","description":"We connect your products with the right audience at the right place and time. Tasting activities, product distribution and creative field executions let consumers get to know and experience your brand up close."},"de":{"title":"Sampling und Verkostungen","description":"Wir bringen Ihre Produkte zur richtigen Zeit am richtigen Ort zur richtigen Zielgruppe. Mit Verkostungen, Produktverteilungen und kreativen Aktionen vor Ort erleben Konsumenten Ihre Marke hautnah."}}'::jsonb where title = 'Sampling ve Tadım Etkinlikleri' and i18n is null;
update services set i18n = '{"en":{"title":"Stand Design and Production","description":"We design, produce and realize eye-catching, functional stands that reflect your brand identity. At trade fairs, festivals and event venues we manage everything from design to production, installation to dismantling."},"de":{"title":"Standdesign und Standbau","description":"Wir entwerfen, produzieren und realisieren auffällige, funktionale Stände, die Ihre Markenidentität widerspiegeln. Auf Messen, Festivals und Eventflächen betreuen wir alles von Design und Produktion bis zu Aufbau und Abbau."}}'::jsonb where title = 'Stand Tasarımı ve Üretimi' and i18n is null;
update services set i18n = '{"en":{"title":"Corporate Events and Organizations","description":"From in-house celebrations to New Year''s parties, from motivation events to private invitations, we turn every moment into an unforgettable experience. We design events that bring employees together and put fun and team spirit first."},"de":{"title":"Firmenevents und Organisation","description":"Von internen Feiern über Silvesterpartys bis zu Motivationsevents und privaten Einladungen verwandeln wir jeden Moment in ein unvergessliches Erlebnis. Wir gestalten Veranstaltungen, die Mitarbeitende zusammenbringen und Spaß sowie Teamgeist in den Mittelpunkt stellen."}}'::jsonb where title = 'Kurumsal Etkinlikler ve Organizasyonlar' and i18n is null;
update services set i18n = '{"en":{"title":"University Festivals and Career Days","description":"We bring your brand together with the energy of campuses! From university festivals to career days, from brand presentations to fun experience areas, we plan and run events that let you communicate directly with young people."},"de":{"title":"Uni-Festivals und Karrieretage","description":"Wir bringen Ihre Marke mit der Energie der Campus zusammen! Von Uni-Festivals über Karrieretage und Markenpräsentationen bis zu spaßigen Erlebnisflächen planen und realisieren wir Events, mit denen Sie direkt mit jungen Menschen in Kontakt treten."}}'::jsonb where title = 'Üniversite Şenlikleri ve Kariyer Günleri' and i18n is null;
update services set i18n = '{"en":{"title":"Meeting and Event Management","description":"From dealer meetings to launches, company gatherings to private invitations, we plan all your events professionally. From venue selection to technical infrastructure, stage and decoration to operations management, we think of every detail for you."},"de":{"title":"Meeting- und Eventmanagement","description":"Von Händlertreffen über Produktlaunches und Firmentreffen bis zu privaten Einladungen planen wir all Ihre Veranstaltungen professionell. Von der Locationwahl über Technik und Bühne bis zu Dekoration und Operations kümmern wir uns um jedes Detail."}}'::jsonb where title = 'Toplantı ve Organizasyon Yönetimi' and i18n is null;
update stats set i18n = '{"en":{"label":"Completed projects"},"de":{"label":"Abgeschlossene Projekte"}}'::jsonb where label = 'Tamamlanan proje' and i18n is null;
update stats set i18n = '{"en":{"label":"Brands we work with"},"de":{"label":"Betreute Marken"}}'::jsonb where label = 'Birlikte çalışılan marka' and i18n is null;
update stats set i18n = '{"en":{"label":"Cities with field operations"},"de":{"label":"Städte mit Einsätzen vor Ort"}}'::jsonb where label = 'Saha operasyonu yapılan şehir' and i18n is null;
update stats set i18n = '{"en":{"label":"Year founded"},"de":{"label":"Gründungsjahr"}}'::jsonb where label = 'Kuruluş yılı' and i18n is null;
update process_steps set i18n = '{"en":{"title":"Discovery and brief","description":"We listen to your brand, goals and audience. We clarify your needs and build the project roadmap together."},"de":{"title":"Kennenlernen und Briefing","description":"Wir hören Ihnen zu: Marke, Ziele und Zielgruppe. Wir schärfen Ihre Anforderungen und erarbeiten gemeinsam den Fahrplan des Projekts."}}'::jsonb where title = 'Keşif ve brief' and i18n is null;
update process_steps set i18n = '{"en":{"title":"Concept and planning","description":"We develop a creative concept that fits your goals. We plan venue, team, budget and schedule in full detail."},"de":{"title":"Konzept und Planung","description":"Wir entwickeln ein kreatives Konzept, das zu Ihren Zielen passt. Location, Team, Budget und Zeitplan planen wir bis ins Detail."}}'::jsonb where title = 'Konsept ve planlama' and i18n is null;
update process_steps set i18n = '{"en":{"title":"Field operations and reporting","description":"We coordinate the entire process on site and bring the plan to life. After the event we share the results and our evaluations with you."},"de":{"title":"Umsetzung vor Ort und Reporting","description":"Wir koordinieren den gesamten Ablauf vor Ort und setzen den Plan um. Nach dem Event teilen wir Ergebnisse und Auswertungen mit Ihnen."}}'::jsonb where title = 'Saha operasyonu ve raporlama' and i18n is null;
update form_fields set i18n = '{"en":{"label":"Your name"},"de":{"label":"Ihr Name"}}'::jsonb where id = 'name' and i18n is null;
update form_fields set i18n = '{"en":{"label":"Email"},"de":{"label":"E-Mail"}}'::jsonb where id = 'email' and i18n is null;
update form_fields set i18n = '{"en":{"label":"Phone"},"de":{"label":"Telefon"}}'::jsonb where id = 'phone' and i18n is null;
update form_fields set i18n = '{"en":{"label":"Event type"},"de":{"label":"Veranstaltungsart"}}'::jsonb where id = 'eventType' and i18n is null;
update form_fields set i18n = '{"en":{"label":"Event date"},"de":{"label":"Veranstaltungsdatum"}}'::jsonb where id = 'eventDate' and i18n is null;
update form_fields set i18n = '{"en":{"label":"Your message"},"de":{"label":"Ihre Nachricht"}}'::jsonb where id = 'message' and i18n is null;
update projects set i18n = '{"en":{"name":"[Project name]","brand":"[Brand]","city":"[City]","year":"[Year]"},"de":{"name":"[Projektname]","brand":"[Marke]","city":"[Stadt]","year":"[Jahr]"}}'::jsonb where i18n is null and name = '[Proje adı]';
insert into site_texts (key, value) values
  ('hero_kicker_en', 'Events · Activation · Stands'),
  ('hero_kicker_de', 'Events · Aktivierung · Messestände'),
  ('hero_title_en', 'We turn brands into experiences'),
  ('hero_title_de', 'Wir verwandeln Marken in Erlebnisse'),
  ('hero_subtitle_en', 'At every point where brands meet their target audiences, we bring creative ideas to life through strong field operations.'),
  ('hero_subtitle_de', 'Überall dort, wo Marken auf ihre Zielgruppen treffen, setzen wir kreative Ideen mit starker Umsetzung vor Ort um.'),
  ('about_title_en', 'We bring ideas to life and brands to the field!'),
  ('about_title_de', 'Wir bringen Ideen zum Leben und Marken ins Feld!'),
  ('about_body_1_en', 'We design events that connect brands with people and carefully bring every idea to life on the ground. We take on the whole process from planning to execution; with a strong team, creative solutions and meticulous coordination, we make sure every detail falls into place.'),
  ('about_body_1_de', 'Wir gestalten Events, die Marken mit Menschen zusammenbringen, und setzen jede Idee vor Ort mit Sorgfalt um. Wir übernehmen den gesamten Prozess von der Planung bis zur Umsetzung; mit einem starken Team, kreativen Lösungen und sorgfältiger Koordination sorgen wir dafür, dass jedes Detail sitzt.'),
  ('about_body_2_en', 'Our goal is to turn your brand''s story into moments people take part in, experience and remember. At the heart of our work are open communication, trust and creating together.'),
  ('about_body_2_de', 'Unser Ziel ist es, die Geschichte Ihrer Marke in Momente zu verwandeln, an denen Menschen teilnehmen, die sie erleben und an die sie sich erinnern. Im Mittelpunkt unserer Arbeit stehen offene Kommunikation, Vertrauen und gemeinsames Schaffen.'),
  ('contact_address_en', 'Talatpaşa Mh. Gök Sk. 5, 34400<br>Kağıthane / Istanbul'),
  ('contact_address_de', 'Talatpaşa Mh. Gök Sk. 5, 34400<br>Kağıthane / Istanbul'),
  ('footer_bottom_en', '© 2026 Masterface Event Agency. All rights reserved.'),
  ('footer_bottom_de', '© 2026 Masterface Eventagentur. Alle Rechte vorbehalten.')
on conflict (key) do nothing;
commit;
